async function main() {
  console.log('\n🌱 GOB Health Price List FY 2024-25 — Medicine Seed');
  console.log(`   Catalogue size : ${gobMedicines.length} unique items\n`);

  const hospitals = await prisma.hospital.findMany({
    where:  { status: 'ACTIVE' },
    select: { id: true, name: true, code: true },
  });

  if (!hospitals.length) {
    console.error('❌  No active hospitals found. Run hospital seed first.');
    return;
  }

  console.log(`🏥  Found ${hospitals.length} active hospital(s)`);

  for (const hospital of hospitals) {
    console.log(`\n  ➤  ${hospital.name} (${hospital.code})`);

    // ── Clear existing medicines for this hospital (order matters for FK) ──
    console.log('      🗑️   Clearing existing records...');
    // TransferBatchMapping references StockBatch — must go first
    await prisma.transferBatchMapping.deleteMany({
      where: { sourceBatch: { hospitalId: hospital.id } },
    });
    await prisma.transferItem.deleteMany({
      where: { medicine: { hospitalId: hospital.id } },
    });
    await prisma.returnItem.deleteMany({
      where: { medicine: { hospitalId: hospital.id } },
    });
    await prisma.issueItem.deleteMany({
      where: { medicine: { hospitalId: hospital.id } },
    });
    await prisma.gRNItem.deleteMany({
      where: { medicine: { hospitalId: hospital.id } },
    });
    await prisma.prescriptionItem.deleteMany({
      where: { medicine: { hospitalId: hospital.id } },
    });
    await prisma.purchaseOrderItem.deleteMany({
      where: { medicine: { hospitalId: hospital.id } },
    });
    await prisma.stockBatch.deleteMany({ where: { hospitalId: hospital.id } });
    const deleted = await prisma.medicine.deleteMany({ where: { hospitalId: hospital.id } });
    console.log(`      ✅  Deleted ${deleted.count} old medicines`);

    // ── Insert all catalogue items ─────────────────────────────────────────
    let created = 0;
    let failed  = 0;

    for (const med of gobMedicines) {
      try {
        await prisma.medicine.create({
          data: {
            hospitalId:   hospital.id,
            name:         med.name,
            genericName:  med.genericName,
            strength:     med.strength,
            form:         med.form,
            manufacturer: med.manufacturer,
            status:       'ACTIVE',
          },
        });
        created++;
      } catch (err: any) {
        console.error(`      ❌  ${med.name}:`, err?.message ?? err);
        failed++;
      }
    }

    console.log(`      ✅  Created : ${created}`);
    if (failed) console.log(`      ⚠️   Failed  : ${failed}`);
  }

  console.log('\n✨  Seeding complete!\n');
}

main()
  .catch((e) => { console.error('Seed error:', e); process.exit(1); })
  .finally(async () => { await prisma.$disconnect(); });
